using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEditor;
using UnityEditor.SceneManagement;
using Random=UnityEngine.Random;

// Shared helpers for the V3 world pass (textures generated by tools/texgen, materials, mesh building).
public static class V3
{
    public const string Gen="Assets/Art/Gen/",Dir="Assets/WorldV3";
    public const string RootName="THE CITADEL OF FALLING WATER • reference composition";
    public static Transform Root=>GameObject.Find(RootName).transform;
    public static float RiverX(float z)=>18+Mathf.Sin((z+80)*.023f)*42;
    public static float PathX(float z)=>-104+Mathf.Sin(z*.022f)*5;
    public static float H(float x,float z)=>ReferenceCastleBuilder.Height(x,z);
    public static Color C(string hex){ColorUtility.TryParseHtmlString(hex,out var c);return c;}

    public static string ImportTextures()
    {
        Directory.CreateDirectory(Dir);Directory.CreateDirectory(Dir+"/Meshes");
        int n=0;
        foreach(var f in Directory.GetFiles(Gen,"*.png"))
        {
            string p=f.Replace('\\','/');var imp=AssetImporter.GetAtPath(p) as TextureImporter;
            if(imp==null){AssetDatabase.ImportAsset(p);imp=AssetImporter.GetAtPath(p) as TextureImporter;if(imp==null)continue;}
            string name=Path.GetFileNameWithoutExtension(p);bool normal=name.EndsWith("_n");bool sprite=name.StartsWith("leaf_")||name.StartsWith("flower_")||name.StartsWith("plant_")||name.StartsWith("win_")||name.StartsWith("deco_");
            imp.textureType=normal?TextureImporterType.NormalMap:TextureImporterType.Default;
            imp.sRGBTexture=!normal;imp.mipmapEnabled=true;imp.filterMode=FilterMode.Trilinear;imp.anisoLevel=8;imp.maxTextureSize=1024;imp.npotScale=TextureImporterNPOTScale.None;
            imp.wrapMode=sprite?TextureWrapMode.Clamp:TextureWrapMode.Repeat;
            imp.alphaSource=sprite?TextureImporterAlphaSource.FromInput:TextureImporterAlphaSource.None;imp.alphaIsTransparency=sprite;
            imp.mipMapsPreserveCoverage=sprite;imp.alphaTestReferenceValue=.45f;
            imp.textureCompression=TextureImporterCompression.CompressedHQ;imp.crunchedCompression=false;
            imp.SaveAndReimport();n++;
        }
        return "imported "+n;
    }
    public static Texture2D T(string name)=>AssetDatabase.LoadAssetAtPath<Texture2D>(Gen+name+".png");

    public static Material Mat(string name,string shader)
    {
        string p=Dir+"/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(p);var sh=Shader.Find(shader);
        if(!m){m=new Material(sh){name=name};AssetDatabase.CreateAsset(m,p);}else m.shader=sh;
        m.enableInstancing=true;EditorUtility.SetDirty(m);return m;
    }
    public static Material Lit(string name,string tex,string normal=null,float smooth=.12f,Vector2? tiling=null,string tint="#ffffff")
    {
        var m=Mat(name,"Universal Render Pipeline/Lit");
        m.SetTexture("_BaseMap",T(tex));m.SetColor("_BaseColor",C(tint));m.SetFloat("_Smoothness",smooth);m.SetFloat("_Metallic",0);
        if(normal!=null){m.SetTexture("_BumpMap",T(normal));m.SetFloat("_BumpScale",1f);m.EnableKeyword("_NORMALMAP");}
        var t=tiling??Vector2.one;m.SetTextureScale("_BaseMap",t);m.SetTextureScale("_BumpMap",t);
        m.SetFloat("_Cull",2);EditorUtility.SetDirty(m);return m;
    }
    public static Material Foliage(string name,string tex,string tint="#ffffff",float cutoff=.45f)
    {
        var m=Mat(name,"Aurelia/Natural Foliage");m.SetTexture("_BaseMap",T(tex));m.SetColor("_BaseColor",C(tint));m.SetFloat("_Cutoff",cutoff);EditorUtility.SetDirty(m);return m;
    }

    // ---- mesh building
    public class MB
    {
        public List<Vector3> v=new List<Vector3>();public List<Vector3> n=new List<Vector3>();public List<Vector2> uv=new List<Vector2>();public List<Color> c=new List<Color>();public List<List<int>> subs=new List<List<int>>();
        public MB(int submeshes=1){for(int i=0;i<submeshes;i++)subs.Add(new List<int>());}
        public int Vert(Vector3 p,Vector3 nn,Vector2 u,Color col){v.Add(p);n.Add(nn);uv.Add(u);c.Add(col);return v.Count-1;}
        public void Tri(int sub,int a,int b,int cc){subs[sub].Add(a);subs[sub].Add(b);subs[sub].Add(cc);}
        public void Quad(int sub,Vector3 a,Vector3 b,Vector3 cc,Vector3 d,Vector2 ua,Vector2 ub,Vector2 uc,Vector2 ud,Color col,Vector3? nrm=null)
        {
            var nn=nrm??Vector3.Cross(b-a,d-a).normalized;int i=Vert(a,nn,ua,col);Vert(b,nn,ub,col);Vert(cc,nn,uc,col);Vert(d,nn,ud,col);
            subs[sub].AddRange(new[]{i,i+1,i+2,i,i+2,i+3});
        }
        public void Tri3(int sub,Vector3 a,Vector3 b,Vector3 cc,Vector2 ua,Vector2 ub,Vector2 uc,Color col)
        {
            var nn=Vector3.Cross(b-a,cc-a).normalized;int i=Vert(a,nn,ua,col);Vert(b,nn,ub,col);Vert(cc,nn,uc,col);subs[sub].AddRange(new[]{i,i+1,i+2});
        }
        public Mesh Build(string name)
        {
            var m=new Mesh{name=name,indexFormat=IndexFormat.UInt32};m.SetVertices(v);m.SetNormals(n);m.SetUVs(0,uv);m.SetColors(c);
            var used=subs.Where(s=>s.Count>0).ToList();m.subMeshCount=subs.Count;for(int i=0;i<subs.Count;i++)m.SetTriangles(subs[i],i);m.RecalculateBounds();return m;
        }
    }
    public static Mesh SaveMesh(Mesh m,string file)
    {
        string p=Dir+"/Meshes/"+file+".asset";var ex=AssetDatabase.LoadAssetAtPath<Mesh>(p);
        if(ex){ex.Clear();EditorUtility.CopySerialized(m,ex);Object.DestroyImmediate(m);return ex;}AssetDatabase.CreateAsset(m,p);return m;
    }
    public static Transform FreshGroup(string name,Transform parent=null)
    {
        var old=GameObject.Find(name);if(old)Object.DestroyImmediate(old);var g=new GameObject(name).transform;g.SetParent(parent??Root,false);return g;
    }
    public static GameObject Obj(string name,Mesh mesh,Material[] mats,Transform parent,Vector3? pos=null,Quaternion? rot=null,Vector3? scale=null)
    {
        var g=new GameObject(name);g.transform.SetParent(parent,false);if(pos.HasValue)g.transform.localPosition=pos.Value;if(rot.HasValue)g.transform.localRotation=rot.Value;if(scale.HasValue)g.transform.localScale=scale.Value;
        g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterials=mats;return g;
    }
    // Noise-based perlin helpers
    public static float Fbm(float x,float y,int oct=4){float s=0,a=.5f,f=1;for(int i=0;i<oct;i++){s+=a*Mathf.PerlinNoise(x*f+31.7f*i+500,y*f-17.3f*i+500);f*=2.03f;a*=.5f;}return s/.9375f;}
    public static Vector3 Smooth(Vector3 a,Vector3 b,float t)=>Vector3.Lerp(a,b,t*t*(3-2*t));
}
